export default function CetusLayout() {
  const { transactionModalVisible, transactionData, setTransactionModalVisible } = useTransactionStore()
  const { isOpenWalletModal, onWalletModal } = useAccountStore()
  const { isApp } = useWindowWidth()
  const location = useLocation()
  const { pathname } = useLocation()
  const [chain, setChain] = useState({ name: 'Sui', icon: '/images/icon-Sui@2x.png', label: 'Sui' })
  const chainConfig = {
    currentChain: chain,
    chainsList: [
      { name: 'Sui', icon: '/images/icon-Sui@2x.png', label: 'Sui' },
      { name: 'Aptos', icon: '/images/aptos.png', label: 'Aptos' }
    ],
    onChange: value => setChain(value)
  }

  const [params, setParams] = useState({ email: '', phone: '', id: '' })
  const notifications = {
    params,
    onParamsChange: setParams,
    onSubscribe: () => {}
  }
  const [language, setLanguage] = useState('EN')
  const [preferred, setFreferred] = useState('Suiscan')
  const [node, setNode] = useState('Suiscan')

  const setting = {
    language: {
      options: ['EN English', 'CH 中文'],
      value: language,
      onValueChange: value => setLanguage(value)
    },
    preferred: {
      options: ['Suiscan', 'Sui Explorer'],
      value: preferred,
      onValueChange: value => setFreferred(value)
    },
    rpcNode: {
      options: ['Suiscan', 'SUIscan2'],
      value: node,
      onValueChange: value => setNode(value)
    }
  }
  const { globalLoading, setGlobalLoading } = useGlobalStore()

  const showToTopIcon = useMemo(() => {
    return ['stats'].some(path => pathname.includes(path))
  }, [pathname])

  const [showScrollToTop, setShowScrollToTop] = useState(false)
  const hStackRef = useRef<HTMLDivElement>(null)

  const handleScroll = () => {
    if (hStackRef.current) {
      setShowScrollToTop(hStackRef.current.scrollTop > 100)
    }
  }

  const scrollToTop = () => {
    if (hStackRef.current) {
      hStackRef.current?.scrollTo({ top: 0, behavior: 'instant' })
    }
  }
  const { isScrollTop } = useGlobalStore()

  useEffect(() => {
    if (isScrollTop || pathname) {
      console.log('🚀 ~ useEffect ~ isScrollTop:', isScrollTop)
      scrollToTop()
    }
  }, [pathname, isScrollTop])

  useEffect(() => {
    setTimeout(() => {
      setGlobalLoading(false)
    }, 1000)
    const hStack = hStackRef.current
    if (hStack) {
      console.log('🚀 ~ useEffect ~ hStack:', hStack)
      hStack.addEventListener('scroll', handleScroll)
      return () => hStack.removeEventListener('scroll', handleScroll)
    }
  }, [])
  return (
    <>
      {globalLoading ? (
        <GeneralLoading />
      ) : (
        <Box
          background="bg_primary"
          w="100vw"
          h="100vh"
          minW={{
            base: '100%',
            lg: '1240px'
          }}
          pt={{
            base: '10px',
            lg: '0 '
          }}
        >
          <Header
            logo={{ image: '/images/logo@2x.png', url: '/' }}
            menus={menuList}
            chain={chainConfig}
            notifications={notifications}
            setting={setting}
            isCetusPump={false}
          />
          <Box
            as="div"
            pb={{
              base: '40px',
              lg: '60px'
            }}
            style={{
              width: '100%',
              position: 'relative',
              height: isApp ? 'calc(100vh - 48px)' : 'calc(100vh - 80px)',
              overflowY: 'auto',
              overflowX: 'hidden'
            }}
            ref={hStackRef}
          >
            <VStack w="100%">
              <Flex
                w="100%"
                maxW="1240px"
                p={{
                  base: '0px 8px',
                  lg: '0 20px'
                }}
                justifyContent="center"
                zIndex="1"
              >
                <Outlet />
              </Flex>
            </VStack>
          </Box>
          {showScrollToTop && showToTopIcon && (
            <Block
              cursor="pointer"
              w="40px"
              h="40px"
              p="0"
              borderRadius="12px"
              zIndex="99"
              position="fixed"
              bottom="30px"
              right="20px"
              onClick={scrollToTop}
            >
              <Center w="100%" h="100%">
                <Icon xlinkHref="#icon-icon_top1" onClick={scrollToTop} />
              </Center>
            </Block>
          )}
        </Box>
      )}
      {/* 链接钱包弹窗 */}
      {isOpenWalletModal && <WalletModal isOpen={isOpenWalletModal} onClose={() => onWalletModal(false)} />}
      {/* 交易弹窗 */}
      {transactionModalVisible && transactionData && (
        <TransactionModal
          isOpen={transactionModalVisible}
          onClose={() => {
            setTransactionModalVisible(false)
          }}
          {...transactionData}
        />
      )}
    </>
  )
}
